    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply stimulus and check output synchronously
    task apply_and_check;
        input reg exp_z;
        begin
            @(posedge clk);
            #1; // Small delay to sample after active clock edge
            if (z !== exp_z) begin
                $display("Time %0t: Mismatch! x=%b, z=%b, expected_z=%b", $time, x, z, exp_z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Test 1: Asynchronous Reset Test
        areset = 1;
        #3;
        areset = 0;

        // In State A (after reset)
        // x = 0 -> should stay in A, z = 0
        x = 0;
        apply_and_check(1'b0);

        // x = 0 -> stay in A, z = 0
        x = 0;
        apply_and_check(1'b0);

        // x = 1 -> transition to B, z = 1
        x = 1;
        apply_and_check(1'b1);

        // Now in State B:
        // x = 0 -> stay in B, z = 1
        x = 0;
        apply_and_check(1'b1);

        // x = 1 -> stay in B, z = 0
        x = 1;
        apply_and_check(1'b0);

        // x = 1 -> stay in B, z = 0
        x = 1;
        apply_and_check(1'b0);

        // x = 0 -> stay in B, z = 1
        x = 0;
        apply_and_check(1'b1);

        // Test asynchronous reset mid-operation
        areset = 1;
        #2;
        // Should be back in State A, check output with x = 1 (should give z = 1)
        x = 1;
        #3;
        areset = 0; // release reset
        #1;
        if (z !== 1'b1) begin
            $display("Time %0t: Reset recovery mismatch! z=%b, expected_z=%b", $time, z, 1'b1);
            errors = errors + 1;
        end

        // Finish tests
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
